mapper.select:
SELECT 
FROM policy_applications


        AND application_id = #{q.applicationId}
        AND customer_id = #{q.customerId}
        AND product_type = #{q.productType}
        AND product_name = #{q.productName}
        AND payment_frequency = #{q.paymentFrequency}
        AND status = #{q.status}
        AND created_by = #{q.createdBy}

    AND application_date >= #{dateFrom}
    AND application_date <= #{dateTo}
    AND created_at >= #{createdFrom}
    AND created_at <= #{createdTo}
    AND updated_at >= #{updatedFrom}
    AND updated_at <= #{updatedTo}

ORDER BY updated_at DESC NULLS LAST, application_id

SELECT
    pa.application_id, pa.customer_id, pa.product_type, pa.product_name, pa.coverage_amount,
    pa.premium, pa.payment_frequency, pa.insurance_period, pa.waiting_period,
    pa.beneficiary_relationship, pa.application_date, pa.status, pa.created_by,
    pa.created_at, pa.updated_at,
    ud.decision_id, ud.risk_score, ud.risk_level, ud.underwriting_result,
    ud.premium_adjustment, ud.key_factors
FROM policy_applications pa
LEFT JOIN underwriting_decisions ud ON ud.application_id = pa.application_id


        AND pa.customer_id = #{q.customerId}
        AND pa.product_type = #{q.productType}
        AND pa.product_name = #{q.productName}
        AND pa.payment_frequency = #{q.paymentFrequency}
        AND pa.status = #{q.status}
        AND pa.created_by = #{q.createdBy}
        AND ud.risk_level = #{q.riskLevel}

    AND pa.application_date >= #{dateFrom}
    AND pa.application_date <= #{dateTo}

ORDER BY pa.updated_at DESC NULLS LAST, pa.application_id
